<script setup>
import { computed, ref } from 'vue'
import MapboxMap from '~/components/MapboxMap.vue'
import { getIncidentGuide } from '~/data/reportIncidentGuides'
import { getIncidentIconUrl } from '~/composables/useIncidentIcon'

const props = defineProps({ incident: Object, isHelpRequest: Boolean, isLoading: Boolean, isError: Boolean, userLocation: Object })
defineEmits(['back'])
const isFollowing = ref(false)
const shareLabel = ref('แชร์')
const selectedImage = ref('')
const relativeTime = (value) => { const minutes = Math.max(0, Math.round((Date.now() - new Date(value).getTime()) / 60000)); if (!Number.isFinite(minutes) || minutes < 1) return 'เมื่อสักครู่'; if (minutes < 60) return `${minutes} นาทีที่แล้ว`; const hours = Math.round(minutes / 60); return hours < 24 ? `${hours} ชั่วโมงที่แล้ว` : `${Math.round(hours / 24)} วันที่แล้ว` }
const formatCoordinate = (value) => Number.isFinite(Number(value)) ? Number(value).toFixed(5) : 'ไม่ระบุ'
const formatRadius = (value) => { const radius = Number(value); return !Number.isFinite(radius) || radius <= 0 ? '' : radius >= 1000 ? `${(radius / 1000).toFixed(1)} กม.` : `${Math.round(radius)} เมตร` }
const statusInfo = computed(() => { if (props.isHelpRequest) return { label: 'กำลังรอความช่วยเหลือ', tone: 'pending' }; if (props.incident?.incident_status === 'resolved') return { label: 'สิ้นสุดแล้ว', tone: 'resolved' }; if (props.incident?.verification_status === 'verified') return { label: 'ยืนยันแล้ว', tone: 'verified' }; return props.incident?.final_type_id || props.incident?.type_name ? { label: 'กำลังเกิดขึ้น', tone: 'ongoing' } : { label: 'รอตรวจสอบ', tone: 'pending' } })
const iconUrl = computed(() => props.isHelpRequest ? '/Life-saving.svg' : getIncidentIconUrl({ typeCode: props.incident?.type_code, iconName: props.incident?.icon_name, kind: props.incident?.type_name ? 'incident' : 'pending_report' }))
const reports = computed(() => Array.isArray(props.incident?.reports) ? props.incident.reports : [])
const galleryImages = computed(() => [...new Set(reports.value.flatMap((report) => (report.media || []).filter((media) => media?.media_type === 'image' && media.media_url).map((media) => media.media_url)))])
const mainImage = computed(() => props.incident?.image_url || galleryImages.value[0] || '')
const guide = computed(() => getIncidentGuide(props.incident?.type_code))
const mapItems = computed(() => props.incident ? [{ id: `incident-${props.incident.incident_id}`, kind: props.isHelpRequest ? 'help_request' : 'incident', title: props.incident.title, lat: Number(props.incident.lat), lng: Number(props.incident.lng), markerColor: props.incident.marker_color || '#1479ef', iconUrl: iconUrl.value, displayMode: props.incident.display_mode, radiusM: Number(props.incident.radius_m) || null }] : [])
const distanceFromUser = computed(() => { const item = props.incident; const user = props.userLocation; if (!item || !user) return 'ยังไม่ทราบระยะทาง'; const [lat, lng, userLat, userLng] = [item.lat, item.lng, user.lat, user.lng].map(Number); if (![lat,lng,userLat,userLng].every(Number.isFinite)) return 'ยังไม่ทราบระยะทาง'; const r = (n) => n * Math.PI / 180; const a = Math.sin(r(lat-userLat)/2)**2 + Math.cos(r(userLat))*Math.cos(r(lat))*Math.sin(r(lng-userLng)/2)**2; const meters = 6371000 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a)); return meters < 1000 ? `${Math.max(10, Math.round(meters / 10) * 10)} ม. จากคุณ` : `${(meters / 1000).toFixed(meters < 10000 ? 1 : 0)} กม. จากคุณ` })
const directionsUrl = computed(() => props.incident ? `https://www.google.com/maps/dir/?api=1&destination=${props.incident.lat},${props.incident.lng}` : '#')
const shareIncident = async () => { try { const data = { title: props.incident?.title || 'เหตุการณ์ GeoSpread', url: window.location.href }; if (navigator.share) await navigator.share(data); else await navigator.clipboard?.writeText(data.url); shareLabel.value = 'คัดลอกลิงก์แล้ว' } catch {} }
</script>

<template>
  <section class="incident-detail" @keydown.esc="selectedImage = ''">
    <button type="button" class="incident-detail__back" @click="$emit('back')"><svg viewBox="0 0 24 24"><path d="m14 6-6 6 6 6" /></svg>กลับ</button>
    <h1>{{ isHelpRequest ? 'รายละเอียดคำขอความช่วยเหลือ' : 'รายละเอียดเหตุการณ์' }}</h1>
    <p v-if="isLoading" class="incident-detail__state">กำลังโหลดรายละเอียดเหตุการณ์...</p><p v-else-if="isError || !incident" class="incident-detail__state incident-detail__state--error">ไม่พบเหตุการณ์ที่ต้องการ หรือไม่สามารถโหลดข้อมูลได้</p>
    <div v-else class="incident-detail__grid"><main class="incident-detail__main"><article class="incident-hero"><div class="incident-hero__media" :class="{ 'incident-hero__media--empty': !mainImage }"><img v-if="mainImage" :src="mainImage" :alt="incident.title" /><img v-else :src="iconUrl" alt="" /></div><div class="incident-hero__content"><p class="incident-hero__type"><img :src="iconUrl" alt="" />{{ incident.type_name || 'เหตุการณ์' }}</p><h2>{{ incident.title || 'รายงานเหตุการณ์' }}</h2><span class="incident-status" :class="`incident-status--${statusInfo.tone}`">{{ statusInfo.label }}</span><p class="incident-hero__place">ตำแหน่งที่ได้รับรายงาน</p><p class="incident-hero__meta">อัปเดตล่าสุด {{ relativeTime(incident.last_reported_at) }} · {{ distanceFromUser }}</p></div></article><section class="detail-section"><h2>รายละเอียดเหตุการณ์</h2><p>{{ incident.description || 'ยังไม่มีรายละเอียดเพิ่มเติมจากรายงานนี้' }}</p></section><section v-if="!isHelpRequest" class="detail-section"><div class="detail-section__heading"><h2>รายงานจากชุมชน</h2><span>{{ reports.length }} รายงาน</span></div><div v-if="reports.length" class="community-reports"><article v-for="report in reports" :key="report.report_id" class="community-report"><div class="community-report__topline"><time>{{ relativeTime(report.created_at) }}</time><span class="report-status">{{ report.report_status === 'verified' ? 'ยืนยันแล้ว' : 'รอตรวจสอบ' }}</span></div><p>{{ report.description }}</p><div v-if="report.media?.length" class="community-report__media"><button v-for="media in report.media.filter((item) => item.media_type === 'image')" :key="media.media_id" type="button" @click="selectedImage = media.media_url"><img :src="media.media_url" alt="รูปภาพจากรายงานชุมชน" /></button></div></article></div><p v-else class="detail-section__empty">ยังไม่มีรายงานเพิ่มเติมจากชุมชน</p></section><section v-if="galleryImages.length" class="detail-section"><h2>รูปภาพจากเหตุการณ์</h2><div class="incident-gallery"><button v-for="image in galleryImages.slice(0,4)" :key="image" type="button" @click="selectedImage = image"><img :src="image" alt="รูปภาพเหตุการณ์" /></button></div></section></main><aside class="incident-detail__aside"><section class="aside-card incident-actions"><a v-if="isHelpRequest" :href="directionsUrl" target="_blank" rel="noopener noreferrer">นำทาง</a><button type="button" :class="{ 'incident-actions__follow--active': isFollowing }" @click="isFollowing = !isFollowing">{{ isFollowing ? 'กำลังติดตาม' : 'ติดตามเหตุการณ์' }}</button><button type="button" @click="shareIncident">{{ shareLabel }}</button></section><section class="aside-card location-card"><h2>ตำแหน่งเหตุการณ์</h2><MapboxMap class="location-card__map" :center="[Number(incident.lng), Number(incident.lat)]" :zoom="14" :show-geolocate-control="false" :map-items="mapItems" :selected-item-id="mapItems[0]?.id" :reporter-location="userLocation" /><dl><div><dt>ละติจูด</dt><dd>{{ formatCoordinate(incident.lat) }}</dd></div><div><dt>ลองจิจูด</dt><dd>{{ formatCoordinate(incident.lng) }}</dd></div><div><dt>ระยะจากคุณ</dt><dd>{{ distanceFromUser }}</dd></div></dl></section><section class="aside-card incident-information"><h2>ข้อมูลเหตุการณ์</h2><dl><div><dt>ประเภท</dt><dd>{{ incident.type_name || 'รอตรวจสอบ' }}</dd></div><div><dt>สถานะ</dt><dd>{{ statusInfo.label }}</dd></div><div><dt>รายงานครั้งแรก</dt><dd>{{ relativeTime(incident.first_reported_at) }}</dd></div><div><dt>อัปเดตล่าสุด</dt><dd>{{ relativeTime(incident.last_reported_at) }}</dd></div><div><dt>รายงานที่เกี่ยวข้อง</dt><dd>{{ incident.report_count || reports.length }} รายงาน</dd></div></dl><p v-if="formatRadius(incident.radius_m)" class="incident-information__radius">พื้นที่ได้รับผลกระทบโดยประมาณ: {{ formatRadius(incident.radius_m) }}</p></section><section v-if="!isHelpRequest" class="aside-card safety-guide"><h2>คู่มือความปลอดภัยที่เกี่ยวข้อง</h2><p>{{ guide.guideTitle }}</p><NuxtLink :to="{ path: '/safety-guide', query: { type: incident.type_code } }">ดูคู่มือฉบับเต็ม →</NuxtLink></section></aside></div>
    <div v-if="selectedImage" class="image-lightbox"><button type="button" @click="selectedImage = ''">ปิด</button><img :src="selectedImage" alt="รูปภาพเหตุการณ์ขนาดใหญ่" /></div>
  </section>
</template>

<style scoped>
