display:flex;justify-content:space-between;gap:.75rem}.community-reports{display:grid;gap:.7rem;margin-top:.85rem}.community-report{padding:.85rem;border-radius:.75rem;background:#f8fbff}.community-report p{color:#294b76}.community-report__media,.incident-gallery{display:flex;gap:.5rem;margin-top:.65rem;overflow:auto}.community-report__media button,.incident-gallery button{width:4.2rem;height:4.2rem;flex:0 0 auto;padding:0;overflow:hidden;border:0;border-radius:.6rem;cursor:zoom-in}.community-report__media img,.incident-gallery img{width:100%;height:100%;object-fit:cover}.incident-gallery{display:grid;grid-template-columns:repeat(4,1fr)}.incident-gallery button{width:100%;height:auto;aspect-ratio:1}.incident-actions{display:grid;grid-template-columns:repeat(2,1fr);gap:.55rem}.incident-actions>*{display:inline-flex;align-items:center;justify-content:center;min-height:2.55rem;border:1px solid #bcd5fa;border-radius:.7rem;background:#f5f9ff;color:#2259b5;font:inherit;font-size:.76rem;font-weight:800;text-decoration:none;cursor:pointer}.location-card__map{height:13.5rem;margin:.85rem 0;border-radius:.75rem;overflow:hidden}.location-card dl,.incident-information dl{display:grid;gap:.5rem;margin:0}.location-card dt,.incident-information dt{color:#6c83a1}.location-card dd,.incident-information dd{margin:0;color:#284c78;font-weight:750;text-align:right}.incident-information__radius{padding:.65rem;border-radius:.65rem;background:#f3f7fd;color:#42668f}.safety-guide a{color:#2463c2;font-weight:800}.image-lightbox{position:fixed;z-index:80;inset:0;display:grid;place-items:center;padding:2rem;background:rgb(11 27 54 / 78%)}.image-lightbox img{max-width:100%;max-height:90vh;border-radius:.85rem}.image-lightbox button{position:fixed;top:1rem;right:1rem;padding:.5rem;border:0;border-radius:.5rem;background:#fff;cursor:pointer}@media(max-width:72rem){.incident-detail__grid{grid-template-columns:1fr}.incident-detail__aside{grid-template-columns:repeat(2,1fr)}}@media(max-width:48rem){.incident-detail{padding:1rem}.incident-hero,.incident-detail__aside{grid-template-columns:1fr}.incident-gallery{grid-template-columns:repeat(2,1fr)}}
</style>
